	@Test
	public void retainedRootStepObservesOneNowPerEvaluationAndAFreshNowEachEvaluation() throws Exception {
		String query = "SELECT ?s WHERE { ?s <" + EX + "link> ?o . FILTER(<" + RECORD_NOW_URI + ">(NOW())) }";
		TupleExpr root = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
		LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(new EmptyTripleSource(), null, null,
				0L, new EvaluationStatistics(), false);
		LmdbNativeAggregateCompiler.CompileOutcome outcome = LmdbNativeAggregateCompiler.compileRoot(root,
				new QueryEvaluationContext.Minimal((Dataset) null), strategy, (NativeLmdbQuerySource) dataset);
		assertThat(outcome.isSupported())
				.as("the pattern+filter root must compile natively with a generic filter bridge "
						+ "(precondition for this scope test)")
				.isTrue();
		QueryEvaluationStep step = outcome.step();

		List<Value> firstEvaluation = drainAndCollectNow(step);
		Thread.sleep(25);
		List<Value> secondEvaluation = drainAndCollectNow(step);

		assertThat(firstEvaluation).as("the filter must have run at least once per evaluation").isNotEmpty();
		assertThat(secondEvaluation).isNotEmpty();
		assertThat(new HashSet<>(firstEvaluation))
				.as("all rows of one evaluation must observe one NOW value")
				.hasSize(1);
		assertThat(new HashSet<>(secondEvaluation))
				.as("all rows of one evaluation must observe one NOW value")
				.hasSize(1);
		assertThat(secondEvaluation.get(0))
				.as("a new evaluation of a retained compiled step must observe a fresh NOW value")
				.isNotEqualTo(firstEvaluation.get(0));
	}

	@Test
	public void aggregateHavingAndInteriorShareOneNowPerEvaluation() {
		IRI link = repository.getValueFactory().createIRI(EX, "link");
		StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("link", link), Var.of("o"));
		Group group = new Group(new Filter(pattern, recordNow("s")), List.of("s"));
		group.addGroupElement(new GroupElem("count", new Count(Var.of("o"), false)));
		Filter root = new Filter(group, recordNow("s"));

		QueryEvaluationContext context = new DelayedDatasetContext();
		LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(new EmptyTripleSource(), null, null,
				0L, new EvaluationStatistics(), false);
		LmdbNativeAggregateCompiler.CompileOutcome outcome = LmdbNativeAggregateCompiler.compileRoot(root, context,
				strategy, (NativeLmdbQuerySource) dataset);
		assertThat(outcome.isSupported()).as("the group and HAVING must compile natively").isTrue();

		int rows = 0;
		try (CloseableIteration<BindingSet> result = outcome.step().evaluate(EmptyBindingSet.getInstance())) {
			while (result.hasNext()) {
				result.next();
				rows++;
			}
		}

		List<Value> observed = new ArrayList<>(RECORDED);
		assertThat(rows).as("the true HAVING condition must retain all three groups").isEqualTo(3);
		assertThat(observed)
				.as("three interior rows and three HAVING evaluations must invoke the volatile function once each")
				.hasSize(6);
		assertThat(new HashSet<>(observed))
				.as("the group interior and HAVING must share one query-scoped NOW value")
				.hasSize(1);
	}

	@Test
	public void aggregateHavingAloneOwnsAFreshScopePerEvaluation() throws Exception {
		IRI link = repository.getValueFactory().createIRI(EX, "link");
		StatementPattern pattern = new StatementPattern(Var.of("s"), Var.of("link", link), Var.of("o"));
		Group group = new Group(pattern, List.of("s"));
		group.addGroupElement(new GroupElem("count", new Count(Var.of("o"), false)));
		Filter root = new Filter(group, recordNow("s"));

		LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(new EmptyTripleSource(), null, null,
				0L, new EvaluationStatistics(), false);
		LmdbNativeAggregateCompiler.CompileOutcome outcome = LmdbNativeAggregateCompiler.compileRoot(root,
				new DelayedDatasetContext(), strategy, (NativeLmdbQuerySource) dataset);
		assertThat(outcome.isSupported()).as("a volatile HAVING-only group must compile natively").isTrue();

		List<Value> firstEvaluation = drainAndCollectNow(outcome.step());
		Thread.sleep(25L);
		List<Value> secondEvaluation = drainAndCollectNow(outcome.step());

		assertThat(firstEvaluation).hasSize(3);
		assertThat(secondEvaluation).hasSize(3);
		assertThat(new HashSet<>(firstEvaluation)).hasSize(1);
		assertThat(new HashSet<>(secondEvaluation)).hasSize(1);
		assertThat(secondEvaluation.getFirst())
				.as("a retained group step must not retain HAVING's query scope across evaluations")
				.isNotEqualTo(firstEvaluation.getFirst());
	}

	private static FunctionCall recordNow(String bindingName) {
		return new FunctionCall(RECORD_NOW_URI, new FunctionCall("NOW"), Var.of(bindingName));
	}

	private static List<Value> drainAndCollectNow(QueryEvaluationStep step) {
		RECORDED.clear();
		int rows = 0;
		try (CloseableIteration<BindingSet> iteration = step.evaluate(EmptyBindingSet.getInstance())) {
			while (iteration.hasNext()) {
				iteration.next();
				rows++;
			}
		}
		assertThat(rows).as("the filter accepts everything, so all statements must survive").isEqualTo(3);
		return new ArrayList<>(RECORDED);
	}

